create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,role text not null default 'student' check(role in('student','admin')),created_at timestamptz not null default now());
create table if not exists public.resources(id uuid primary key default gen_random_uuid(),title text not null,subject text not null,year int,type text not null,paper text not null,description text,file_path text not null,file_url text not null,published boolean not null default true,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.saved_resources(user_id uuid references auth.users(id) on delete cascade,resource_id uuid references public.resources(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,resource_id));
alter table public.profiles enable row level security;alter table public.resources enable row level security;alter table public.saved_resources enable row level security;
create policy "profile own read" on public.profiles for select to authenticated using(id=auth.uid());create policy "profile own insert" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "published resources read" on public.resources for select to anon,authenticated using(published=true or created_by=auth.uid());
create policy "admin resource insert" on public.resources for insert to authenticated with check(exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin resource update" on public.resources for update to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and role='admin')) with check(exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin resource delete" on public.resources for delete to authenticated using(exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "saved own read" on public.saved_resources for select to authenticated using(user_id=auth.uid());create policy "saved own insert" on public.saved_resources for insert to authenticated with check(user_id=auth.uid());create policy "saved own delete" on public.saved_resources for delete to authenticated using(user_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public) values('resources','resources',true) on conflict(id) do update set public=true;
create policy "public resource files read" on storage.objects for select to anon,authenticated using(bucket_id='resources');
create policy "admin resource files insert" on storage.objects for insert to authenticated with check(bucket_id='resources' and exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin resource files update" on storage.objects for update to authenticated using(bucket_id='resources' and exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
create policy "admin resource files delete" on storage.objects for delete to authenticated using(bucket_id='resources' and exists(select 1 from public.profiles where id=auth.uid() and role='admin'));
-- After creating your real account: update public.profiles set role='admin' where id='YOUR-USER-UUID';
